CREATE TABLE knowledge_source_lifecycle(library_id TEXT NOT NULL,source_id TEXT NOT NULL,current_revision TEXT NOT NULL,removed INTEGER NOT NULL DEFAULT 0 CHECK(removed IN (0,1)),PRIMARY KEY(library_id,source_id)); INSERT INTO knowledge_source_lifecycle(library_id,source_id,current_revision) SELECT library_id,source_id,revision_id FROM knowledge_sources WHERE rowid IN (SELECT MAX(rowid) FROM knowledge_sources GROUP BY library_id,source_id);
